-- 25. TAY CẦM CHƠI GAME
INSERT INTO product (name, slug, sku, brand_id, price, sale_price, image, cpu, ram, ssd, screen, vga, battery, weight, stock, featured, active, created_at, description, content, promotion, specs, meta_title, meta_description, category_id) VALUES
('Tay cầm Sony DualSense Wireless Controller', 'sony-dualsense-wireless-controller', 'TC-SONY-DS5', @sony, 1990000, 1790000, 'https://m.media-amazon.com/images/I/612bjwBuobS._SL1500_.jpg', NULL, NULL, NULL, NULL, NULL, '1560mAh', '280g', 50, 1, 1, NOW(), 'Tay cầm PS5 Sony DualSense với Haptic Feedback và Adaptive Triggers.', '<h2>Sony DualSense</h2><p>Trải nghiệm chơi game chân thực với Haptic Feedback và Adaptive Triggers trên tay cầm DualSense. Tương thích PS5 và PC.</p>', 'Tặng bọc cần gạt', '{"Kết nối":"Bluetooth/USB-C","Pin":"1560mAh","Tương thích":"PS5, PC, Mac, iOS, Android","Tính năng":"Haptic Feedback, Adaptive Triggers"}', 'Tay cầm Sony DualSense', 'Mua tay cầm Sony DualSense chính hãng giá tốt.', 25),
('Tay cầm Xbox Wireless Controller', 'xbox-wireless-controller', 'TC-MS-XBOX', @microsoft, 1690000, 1490000, 'https://m.media-amazon.com/images/I/51rP0iYfFjL._SL1500_.jpg', NULL, NULL, NULL, NULL, NULL, 'Pin AA', '275g', 40, 1, 1, NOW(), 'Tay cầm Xbox Wireless thế hệ mới tương thích PC, Xbox Series X/S.', '<h2>Xbox Wireless Controller</h2><p>Thiết kế công thái học hiện đại, D-pad mới và nút Share chuyên dụng. Hỗ trợ kết nối Xbox Wireless và Bluetooth.</p>', 'Tặng pin AA Energizer', '{"Kết nối":"Xbox Wireless, Bluetooth, USB-C","Pin":"2x AA","Tương thích":"Xbox Series X/S, PC, Android, iOS","Tính năng":"Nút Share, D-pad Hybrid"}', 'Tay cầm Xbox Wireless Controller', 'Mua tay cầm Xbox Wireless chính hãng Microsoft.', 25),
('Tay cầm 8BitDo Ultimate Bluetooth', '8bitdo-ultimate-bluetooth', 'TC-8B-ULT', @bitdo, 1490000, 1290000, 'https://m.media-amazon.com/images/I/61j63m8iR3L._SL1500_.jpg', NULL, NULL, NULL, NULL, NULL, '1000mAh', '228g', 30, 0, 1, NOW(), 'Tay cầm 8BitDo Ultimate với Hall Effect Joystick, đi kèm Dock sạc.', '<h2>8BitDo Ultimate Bluetooth</h2><p>Đỉnh cao tay cầm chơi game với cần gạt Hall Effect chống trôi, đi kèm dock sạc vô cùng tiện lợi. Hỗ trợ phần mềm tùy chỉnh sâu.</p>', 'Tặng kèm Dock sạc', '{"Kết nối":"Bluetooth/2.4G/USB-C","Pin":"1000mAh (22 giờ)","Tương thích":"Switch, Windows","Tính năng":"Hall Effect Joystick, Dock sạc"}', 'Tay cầm 8BitDo Ultimate Bluetooth', 'Tay cầm 8BitDo Ultimate Bluetooth chính hãng kèm Dock sạc.', 25);

-- 26. GIÁ TREO TAI NGHE
INSERT INTO product (name, slug, sku, brand_id, price, sale_price, image, cpu, ram, ssd, screen, vga, battery, weight, stock, featured, active, created_at, description, content, promotion, specs, meta_title, meta_description, category_id) VALUES
('Giá treo tai nghe Razer Base Station V2 Chroma', 'razer-base-station-v2-chroma', 'GT-RZ-BSV2', @razer, 1890000, 1690000, 'https://m.media-amazon.com/images/I/61XzT0x7H1L._SL1500_.jpg', NULL, NULL, NULL, NULL, NULL, NULL, '460g', 20, 1, 1, NOW(), 'Giá treo tai nghe Razer tích hợp hub USB và LED RGB Chroma.', '<h2>Razer Base Station V2 Chroma</h2><p>Giá treo tai nghe kiêm USB Hub cao cấp từ Razer, trang bị 2 cổng USB 3.1 và DAC âm thanh vòm 7.1, LED Chroma 16.8 triệu màu.</p>', 'Freeship toàn quốc', '{"Cổng kết nối":"2x USB 3.1, 1x 3.5mm combo","LED":"Razer Chroma RGB","DAC":"Âm thanh vòm 7.1","Chất liệu":"Nhôm"}', 'Giá treo tai nghe Razer Base Station V2', 'Giá treo tai nghe RGB cao cấp Razer Base Station V2 Chroma.', 26),
('Giá treo tai nghe Corsair ST100 RGB', 'corsair-st100-rgb', 'GT-CS-ST100', @corsair, 1790000, 1590000, 'https://m.media-amazon.com/images/I/61xJjO-HkLL._SL1500_.jpg', NULL, NULL, NULL, NULL, NULL, NULL, '700g', 15, 0, 1, NOW(), 'Giá treo Corsair ST100 cao cấp với nhôm nguyên khối, LED RGB và DAC 7.1.', '<h2>Corsair ST100 RGB</h2><p>Được làm từ nhôm cao cấp, ST100 tích hợp LED RGB 9 vùng, 2 cổng USB 3.1 và DAC 7.1 mang lại trải nghiệm âm thanh sống động.</p>', 'Freeship', '{"Cổng kết nối":"2x USB 3.1, 1x 3.5mm","LED":"RGB 9 vùng","DAC":"Virtual 7.1 surround","Chất liệu":"Nhôm nguyên khối"}', 'Giá treo tai nghe Corsair ST100 RGB', 'Giá treo tai nghe nhôm Corsair ST100 RGB.', 26);

