INSERT INTO product (name, slug, sku, brand_id, price, sale_price, image, cpu, ram, ssd, screen, vga, battery, weight, stock, featured, active, created_at, description, content, promotion, specs, meta_title, meta_description, category_id) VALUES
('Chuột Logitech G Pro X Superlight', 'logitech-g-pro-x-superlight', 'CG-LG-GPXS', @logitech, 3490000, 2990000, 'https://m.media-amazon.com/images/I/51uy8gOG-iL._SL1500_.jpg', NULL, NULL, NULL, NULL, NULL, '70 giờ', '63g', 45, 1, 1, NOW(), 'Chuột gaming không dây siêu nhẹ Logitech G Pro X Superlight, cảm biến HERO 25K.', '<h2>Logitech G Pro X Superlight</h2><p>Chuột gaming không dây siêu nhẹ (dưới 63g), công nghệ LIGHTSPEED và cảm biến HERO 25K chính xác nhất của Logitech.</p>', 'Tặng feet chuột PTFE', '{"Cảm biến":"HERO 25K","DPI":"25,600","Trọng lượng":"<63g","Kết nối":"LIGHTSPEED Wireless","Pin":"70 giờ"}', 'Logitech G Pro X Superlight', 'Chuột Logitech G Pro X Superlight siêu nhẹ.', 27),
('Chuột Razer DeathAdder V3 Pro', 'razer-deathadder-v3-pro', 'CG-RZ-DAV3P', @razer, 3690000, 3190000, 'https://m.media-amazon.com/images/I/51rRtbFpDbL._SL1500_.jpg', NULL, NULL, NULL, NULL, NULL, '90 giờ', '63g', 30, 1, 1, NOW(), 'Chuột Razer DeathAdder V3 Pro siêu nhẹ, công thái học, cảm biến Focus Pro 30K.', '<h2>Razer DeathAdder V3 Pro</h2><p>Thiết kế công thái học huyền thoại nay nhẹ hơn bao giờ hết (63g), cảm biến Focus Pro 30K Optical và switch quang học thế hệ 3.</p>', 'Tặng Grip Tape', '{"Cảm biến":"Focus Pro 30K Optical","DPI":"30,000","Trọng lượng":"63g","Kết nối":"Razer HyperSpeed Wireless","Pin":"90 giờ"}', 'Razer DeathAdder V3 Pro', 'Chuột gaming Razer DeathAdder V3 Pro chính hãng.', 27);

-- 28. USB
INSERT INTO product (name, slug, sku, brand_id, price, sale_price, image, cpu, ram, ssd, screen, vga, battery, weight, stock, featured, active, created_at, description, content, promotion, specs, meta_title, meta_description, category_id) VALUES
('USB SanDisk Ultra Dual Drive Luxe Type-C 128GB', 'sandisk-ultra-dual-drive-luxe-128gb', 'USB-SD-128G', @sandisk, 450000, 350000, 'https://m.media-amazon.com/images/I/61U7T1koQqL._SL1500_.jpg', NULL, NULL, NULL, NULL, NULL, NULL, '20g', 100, 0, 1, NOW(), 'USB SanDisk 128GB kim loại, 2 đầu Type-C và Type-A tốc độ 150MB/s.', '<h2>SanDisk Ultra Dual Drive Luxe</h2><p>Chép dữ liệu dễ dàng giữa điện thoại USB-C và máy tính với USB vỏ kim loại cao cấp, tốc độ đọc 150MB/s.</p>', 'Bảo hành 5 năm', '{"Dung lượng":"128GB","Giao tiếp":"USB Type-C & Type-A","Tốc độ đọc":"150MB/s","Chất liệu":"Kim loại"}', 'USB SanDisk Type-C 128GB', 'USB SanDisk Ultra Dual Drive Luxe Type-C 128GB.', 28),
('USB Kingston DataTraveler Max 256GB', 'kingston-datatraveler-max-256gb', 'USB-KS-MAX256', @kingston, 990000, 850000, 'https://m.media-amazon.com/images/I/51r-E1qQ0QL._SL1500_.jpg', NULL, NULL, NULL, NULL, NULL, NULL, '12g', 60, 1, 1, NOW(), 'USB Type-C cực nhanh với tốc độ lên đến 1000MB/s chuẩn USB 3.2 Gen 2.', '<h2>Kingston DataTraveler Max</h2><p>Tốc độ phá vỡ kỷ lục đối với một chiếc USB flash drive. Lên đến 1000MB/s đọc và 900MB/s ghi chuẩn USB 3.2 Gen 2.</p>', 'Tặng dây đeo', '{"Dung lượng":"256GB","Giao tiếp":"USB Type-C 3.2 Gen 2","Tốc độ đọc":"1000MB/s","Tốc độ ghi":"900MB/s"}', 'USB Kingston DataTraveler Max 256GB', 'USB Kingston DT Max 256GB Type-C siêu tốc.', 28);

