('USB Wifi TP-Link Archer T3U AC1300', 'tp-link-archer-t3u-ac1300', 'UWF-TP-T3U', @tplink, 350000, 250000, 'https://m.media-amazon.com/images/I/61r5T7GZ42L._SL1500_.jpg', NULL, NULL, NULL, NULL, NULL, NULL, '10g', 100, 0, 1, NOW(), 'USB Wifi thu sóng băng tần kép AC1300 cực nhỏ gọn.', '<h2>TP-Link Archer T3U</h2><p>Kích thước mini gọn nhẹ, công nghệ MU-MIMO cho trải nghiệm mạng không dây tốc độ cao AC1300 trên PC/Laptop.</p>', 'Giảm 50K', '{"Chuẩn Wifi":"AC1300","Băng tần":"Kép (2.4GHz/5GHz)","Giao tiếp":"USB 3.0","Kích thước":"Siêu nhỏ"}', 'USB Wifi TP-Link Archer T3U', 'USB Wifi thu sóng TP-Link Archer T3U AC1300.', 31);

-- 32. CÁP MẠNG
INSERT INTO product (name, slug, sku, brand_id, price, sale_price, image, cpu, ram, ssd, screen, vga, battery, weight, stock, featured, active, created_at, description, content, promotion, specs, meta_title, meta_description, category_id) VALUES
('Cáp mạng Ugreen Cat8 RJ45 Dẹt 2m', 'cap-mang-ugreen-cat8-det-2m', 'CM-UG-CAT8-2M', @ugreen, 199000, 149000, 'https://m.media-amazon.com/images/I/71u9iU3zI-L._SL1500_.jpg', NULL, NULL, NULL, NULL, NULL, NULL, '80g', 150, 0, 1, NOW(), 'Cáp mạng LAN Ugreen chuẩn Cat8, thiết kế dây dẹt, tốc độ 40Gbps.', '<h2>Ugreen Cat8 Ethernet Cable</h2><p>Cáp mạng Cat8 tốc độ siêu tốc 40Gbps/2000MHz. Thiết kế dẹt dễ dàng đi dây dưới thảm hoặc góc tường.</p>', 'Mua 2 tặng 1', '{"Chuẩn":"Cat 8","Tốc độ":"40Gbps / 2000MHz","Chiều dài":"2 mét","Thiết kế":"Dây dẹt","Chất liệu":"Lõi đồng nguyên chất"}', 'Cáp mạng Ugreen Cat8 2m', 'Cáp mạng Ugreen Cat8 tốc độ 40Gbps.', 32),
('Cáp mạng Baseus Cat7 Bện Nilon 3m', 'cap-mang-baseus-cat7-3m', 'CM-BS-CAT7-3M', @baseus, 150000, 99000, 'https://m.media-amazon.com/images/I/61YhO148D1L._SL1500_.jpg', NULL, NULL, NULL, NULL, NULL, NULL, '100g', 200, 0, 1, NOW(), 'Cáp mạng LAN Baseus chuẩn Cat7, dây bện nilon chống đứt, tốc độ 10Gbps.', '<h2>Baseus Cat7 Ethernet Cable</h2><p>Cáp mạng siêu bền bọc vải dù nilon, đầu cáp mạ vàng chống nhiễu, chuẩn Cat7 10Gbps ổn định cho gaming và streaming.</p>', 'Freeship', '{"Chuẩn":"Cat 7","Tốc độ":"10Gbps / 600MHz","Chiều dài":"3 mét","Vật liệu":"Bện Nilon chống đứt"}', 'Cáp mạng Baseus Cat7 3m', 'Cáp mạng LAN Baseus Cat7 3m siêu bền.', 32);

-- 33. CAMERA WIFI
INSERT INTO product (name, slug, sku, brand_id, price, sale_price, image, cpu, ram, ssd, screen, vga, battery, weight, stock, featured, active, created_at, description, content, promotion, specs, meta_title, meta_description, category_id) VALUES
('Camera Wifi Xiaomi Smart Camera C300', 'xiaomi-smart-camera-c300', 'CAM-XM-C300', @xiaomi, 890000, 690000, 'https://m.media-amazon.com/images/I/51wXF1R6kEL._SL1500_.jpg', NULL, NULL, NULL, NULL, NULL, NULL, '327g', 60, 1, 1, NOW(), 'Camera IP Wifi Xiaomi C300 độ phân giải 2K, xoay 360 độ, theo dõi chuyển động AI.', '<h2>Xiaomi Smart Camera C300</h2><p>Độ phân giải 2K siêu nét, khẩu độ F1.4 thu sáng tốt trong đêm. Xoay 360 độ quan sát toàn cảnh, đàm thoại 2 chiều rõ ràng.</p>', 'Tặng thẻ nhớ 32GB', '{"Độ phân giải":"2K (2304x1296)","Góc nhìn":"360° ngang, 108° dọc","Lưu trữ":"Thẻ nhớ MicroSD (tối đa 256GB)","Kết nối":"Wi-Fi 2.4GHz","Tính năng":"Đàm thoại 2 chiều, Night Vision, AI Human Detection"}', 'Camera Wifi Xiaomi C300 2K', 'Camera an ninh Xiaomi C300 2K.', 33),
('Camera Wifi TP-Link Tapo C200', 'tp-link-tapo-c200', 'CAM-TP-C200', @tplink, 650000, 490000, 'https://m.media-amazon.com/images/I/61kM50P4vWL._SL1500_.jpg', NULL, NULL, NULL, NULL, NULL, NULL, '260g', 80, 0, 1, NOW(), 'Camera IP Wifi TP-Link Tapo C200 1080p, xoay 360 độ, phát hiện chuyển động.', '<h2>TP-Link Tapo C200</h2><p>Camera an ninh gia đình giá rẻ, xoay 360 độ, quay phim Full HD 1080p. Hỗ trợ cảnh báo âm thanh và ánh sáng khi phát hiện kẻ gian.</p>', 'Tặng thẻ nhớ 32GB', '{"Độ phân giải":"1080p Full HD","Góc nhìn":"360° ngang, 114° dọc","Lưu trữ":"Thẻ nhớ MicroSD (tối đa 128GB)","Kết nối":"Wi-Fi 2.4GHz","Tính năng":"Night Vision, Đàm thoại 2 chiều"}', 'Camera Wifi TP-Link Tapo C200', 'Camera an ninh TP-Link Tapo C200 1080p.', 33);
